if (start_idx == end_idx) return {graph.nodes[start_idx]};

const size_t n = graph.nodes.size();
std::vector<double> g_score(n, std::numeric_limits<double>::infinity());
std::vector<double> f_score(n, std::numeric_limits<double>::infinity());
std::vector<int> came_from(n, -1);
std::vector<bool> in_open(n, false);

g_score[start_idx] = 0.0;
f_score[start_idx] = graph.heuristic(start_idx, end_idx);

auto cmp = [&f_score](int lhs, int rhs) { return f_score[lhs] > f_score[rhs]; };
std::priority_queue<int, std::vector<int>, decltype(cmp)> open_q(cmp);
open_q.push(start_idx);
in_open[start_idx] = true;

while (!open_q.empty()) {
    int current = open_q.top();
    open_q.pop();
    in_open[current] = false;

    if (current == end_idx) {
        std::vector<Node> path;
        for (int at = end_idx; at != -1; at = came_from[at]) {
            path.push_back(graph.nodes[at]);
        }
        std::reverse(path.begin(), path.end());
        return path;
    }

    for (const auto& edge : graph.adjacency[current]) {
        int neighbor = edge.to;
        double tentative = g_score[current] + edge.weight;
        if (tentative < g_score[neighbor]) {
            came_from[neighbor] = current;
            g_score[neighbor] = tentative;
            f_score[neighbor] = tentative + graph.heuristic(neighbor, end_idx);
            if (!in_open[neighbor]) {
                open_q.push(neighbor);
                in_open[neighbor] = true;
            }
        }
    }
}
return {};
// END_CODE

